//go:build linux

package cache

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"golang.org/x/sys/unix"
)

// Call only with the inode and bytes fixed when the test created its own
// payload. Generic worker inspection never calls a payload reader.
func dsgVerifyGeneratedAllocation(ctx context.Context, parent int, name string, expectedInode uint64, expectedSHA256 string, expectedLength int64) error {
	if ctx.Err() != nil || expectedInode == 0 || expectedLength < 0 || expectedLength > 64<<10 ||
		!dsgDigest.MatchString(expectedSHA256) {
		return ErrDSGExactPreserve
	}
	anchor, err := dsgAllocationStatAt(parent, "")
	if err != nil || anchor.UID != uint32(os.Geteuid()) || anchor.Mode&unix.S_IFMT != unix.S_IFDIR || anchor.Mode&0022 != 0 {
		return ErrDSGExactPreserve
	}
	st, err := dsgAllocationChild(parent, name, anchor)
	if err != nil || st.Mode&unix.S_IFMT != unix.S_IFREG || st.Links != 1 ||
		st.Inode != expectedInode || st.Size != uint64(expectedLength) {
		return ErrDSGExactPreserve
	}
	file, err := dsgAllocationOpen(parent, name, st, 0)
	if err != nil {
		return err
	}
	defer file.Close()
	sum := sha256.New()
	n, err := io.Copy(sum, io.LimitReader(file, expectedLength+1))
	if err != nil || n != expectedLength || hex.EncodeToString(sum.Sum(nil)) != expectedSHA256 || ctx.Err() != nil {
		return ErrDSGExactPreserve
	}
	for _, item := range []struct {
		fd   int
		name string
		want dsgAllocationStat
	}{
		{int(file.Fd()), "", st}, {parent, name, st}, {parent, "", anchor},
	} {
		if got, err := dsgAllocationStatAt(item.fd, item.name); err != nil || got != item.want {
			return ErrDSGExactPreserve
		}
	}
	return nil
}

func TestDSGGraphNativeAllocationMetadataOnly(t *testing.T) {
	f := dsgNewGraphFixture(t)
	leaf := filepath.Join(f.allocation, "generated-data")
	require.NoError(t, os.WriteFile(leaf, []byte("generated bytes"), 0600))
	oldTime := time.Unix(1_600_000_000, 0)
	require.NoError(t, os.Chtimes(leaf, oldTime, oldTime))
	var beforeStat, afterStat unix.Stat_t
	require.NoError(t, unix.Lstat(leaf, &beforeStat))
	before := f.observe(t)
	require.NoError(t, unix.Lstat(leaf, &afterStat))
	require.Equal(t, beforeStat.Atim, afterStat.Atim)
	require.NotNil(t, before.Allocations)
	require.NotNil(t, before.Allocations.Snapshot)
	require.NotNil(t, before.Allocations.Blob)
	require.Regexp(t, dsgDigest, before.Allocations.Snapshot.MetadataSHA256)
	require.Regexp(t, dsgDigest, before.Allocations.Blob.MetadataSHA256)
	var rootStat unix.Stat_t
	require.NoError(t, unix.Lstat(f.allocation, &rootStat))
	require.Equal(t, rootStat.Ino, before.Allocations.Snapshot.RootInode)
	require.Equal(t, 2, before.Allocations.Snapshot.Entries)
	require.Equal(t, 1, before.Allocations.Blob.Entries)
	require.False(t, before.Allocations.Snapshot.ContentVerified)
	require.False(t, before.Allocations.Blob.ContentVerified)
	require.Equal(t, strings.Repeat("a", 64), before.Allocations.Blob.DeclaredSHA256)
	require.Contains(t, before.Unverified, "native_allocation_contents")
	require.Equal(t, "preserve", before.Disposition)
	raw, err := json.Marshal(before.Allocations)
	require.NoError(t, err)
	require.NotContains(t, string(raw), filepath.Base(leaf))
	require.Equal(t, before, f.observe(t))

	require.NoError(t, os.Chmod(leaf, 0400))
	after := f.observe(t)
	require.NotNil(t, after.Allocations)
	require.NotNil(t, after.Allocations.Snapshot)
	require.NotEqual(t, before.Allocations.Snapshot.MetadataSHA256, after.Allocations.Snapshot.MetadataSHA256)
	require.Equal(t, before.Allocations.Blob, after.Allocations.Blob)
	require.NotEqual(t, before.EvidenceHash, after.EvidenceHash)
}

func TestDSGGraphNativeAllocationFailsClosed(t *testing.T) {
	for _, test := range []struct {
		name  string
		setup func(*testing.T, *dsgGraphFixture)
	}{
		{"symlink", func(t *testing.T, f *dsgGraphFixture) {
			require.NoError(t, os.Symlink(f.blobFile, filepath.Join(f.allocation, "link")))
		}},
		{"outside-hardlink", func(t *testing.T, f *dsgGraphFixture) {
			outside := filepath.Join(t.TempDir(), "generated")
			require.NoError(t, os.WriteFile(outside, nil, 0600))
			require.NoError(t, os.Link(outside, filepath.Join(f.allocation, "link")))
		}},
		{"special-file", func(t *testing.T, f *dsgGraphFixture) {
			require.NoError(t, unix.Mkfifo(filepath.Join(f.allocation, "fifo"), 0600))
		}},
		{"untrusted-directory", func(t *testing.T, f *dsgGraphFixture) {
			path := filepath.Join(f.allocation, "writable")
			require.NoError(t, os.Mkdir(path, 0700))
			require.NoError(t, os.Chmod(path, 0770))
		}},
		{"depth-bound", func(t *testing.T, f *dsgGraphFixture) {
			path := filepath.Join(f.allocation, strings.Repeat("dir/", dsgAllocationMaxDepth))
			require.NoError(t, os.MkdirAll(path, 0700))
		}},
	} {
		t.Run(test.name, func(t *testing.T) {
			f := dsgNewGraphFixture(t)
			test.setup(t, f)
			got := f.observe(t)
			require.NotNil(t, got.Allocations)
			require.Nil(t, got.Allocations.Snapshot)
			require.NotNil(t, got.Allocations.Blob)
			require.Contains(t, got.Unverified, "native_snapshot_allocation_ownership")
			require.Equal(t, "preserve", got.Disposition)
		})
	}
	t.Run("mount-identity", func(t *testing.T) {
		f := dsgNewGraphFixture(t)
		fd := int(f.worker.Fd())
		anchor, err := dsgAllocationStatAt(fd, "")
		require.NoError(t, err)
		anchor.MountID++
		_, err = dsgAllocationChild(fd, "snapshots", anchor)
		require.ErrorIs(t, err, ErrDSGExactPreserve)
	})
}

func TestDSGGraphNativeAllocationGeneratedPayload(t *testing.T) {
	root := t.TempDir()
	parent, err := os.Open(root)
	require.NoError(t, err)
	t.Cleanup(func() { require.NoError(t, parent.Close()) })
	fd := int(parent.Fd())
	const name, payload = "generated", "synthetic allocation bytes"
	path := filepath.Join(root, name)
	require.NoError(t, os.WriteFile(path, []byte(payload), 0600))
	st, err := dsgAllocationStatAt(fd, name)
	require.NoError(t, err)
	sum := sha256.Sum256([]byte(payload))
	sha, length := hex.EncodeToString(sum[:]), int64(len(payload))
	require.NoError(t, dsgVerifyGeneratedAllocation(t.Context(), fd, name, st.Inode, sha, length))
	require.ErrorIs(t, dsgVerifyGeneratedAllocation(t.Context(), fd, name, st.Inode, sha, length+1), ErrDSGExactPreserve)
	require.ErrorIs(t, dsgVerifyGeneratedAllocation(t.Context(), fd, name, st.Inode+1, sha, length), ErrDSGExactPreserve)
	require.NoError(t, os.WriteFile(path, []byte(strings.Repeat("x", len(payload))), 0600))
	require.ErrorIs(t, dsgVerifyGeneratedAllocation(t.Context(), fd, name, st.Inode, sha, length), ErrDSGExactPreserve)
}
